import { useState } from "react";
export default function Form11() {
  const [forminput, setforminput] = useState({
    name: "",
    email: "",
    age: "",
    enfo: "",
    town: " ",
  });
  return (
    <>
      <form
        onSubmit={(ev) => {
          ev.preventDefault();
        }}
      >
        <label> name</label>
        <input
          value={forminput.name}
          onChange={(as) => {
            setforminput({ ...forminput, name: as.target.value });
          }}
        />
        <label> email</label>
        <input
          value={forminput.email}
          onChange={(as) => {
            setforminput({ ...forminput, email: as.target.value });
          }}
        />
        <label> age</label>
        <input
          value={forminput.age}
          onChange={(as) => {
            setforminput({ ...forminput, age: as.target.value });
          }}
        />
        <hr></hr>
        <label> inputtext</label>
        <textarea
          value={forminput.enfo}
          onChange={(as) => {
            setforminput({ ...forminput, enfo: as.target.value });
          }}
        />
        <></>
        <select
          value={forminput.town}
          onChange={(as) => {
            setforminput({ ...forminput, town: as.target.value });
          }}
        >
          <option>ksa</option>
          <option>ps</option>
        </select>
        <button>sumbet</button>
      </form>
    </>
  );
}
